const TIERS={"ruled": {"label": "Ruled", "def": "A court or regulator found against Meta."}, "appeal": {"label": "Ruled, under appeal", "def": "A court or regulator found against Meta, and Meta is appealing."}, "settled": {"label": "Settled", "def": "Meta paid or agreed to changes without admitting wrongdoing."}, "admitted": {"label": "Admitted", "def": "Meta acknowledged it, apologized, or published it itself."}, "reported": {"label": "Reported", "def": "Documented by journalists, researchers or Meta’s own files, with no legal finding."}, "alleged": {"label": "Alleged", "def": "Claims in a pending case or a preliminary regulatory finding."}, "dismissed": {"label": "Dismissed", "def": "A court ruled for Meta. Listed so the record stays fair."}};
const THEMES={"privacy": "Privacy and data", "lgbtq": "LGBTQ+ people", "abroad": "Violence abroad", "kids": "Kids and teens", "democracy": "Elections and misinformation", "rights": "Discrimination", "labor": "Workers", "scams": "Scams", "market": "Competition"};
const ENTRIES=[{"id": "beacon", "date": "2007-11", "title": "Beacon broadcasts what people buy", "tier": "settled", "themes": ["privacy"], "summary": "Beacon told users’ friends what they bought or rented on partner websites, and it was switched on unless people opted out. Zuckerberg apologized a month after launch. Facebook shut Beacon down in 2009 to settle a class action.", "fig": "$9.5M", "cap": "settlement, used to fund an online privacy foundation", "response": "“We’ve made a lot of mistakes building this feature, but we’ve made even more with how we’ve handled them.”", "who": "Mark Zuckerberg, 2007", "sources": [["NBC News", "https://www.nbcnews.com/news/amp/wbna32956166"], ["Wikipedia", "https://en.wikipedia.org/wiki/Facebook_Beacon"]], "slug": "2007-beacon-broadcasts-what-people-buy", "url": "/record/2007-beacon-broadcasts-what-people-buy/"}, {"id": "privacy2009", "date": "2009-12", "title": "Private settings made public without warning", "tier": "settled", "themes": ["privacy"], "summary": "According to the FTC, Facebook changed its site so that information users may have marked private, such as friend lists, became public, without warning them or asking first. It also let apps reach nearly all of a user’s personal data. Facebook settled in 2011.", "fig": "20 years", "cap": "of independent privacy audits; no fine", "sources": [["FTC press release", "https://www.ftc.gov/news-events/news/press-releases/2011/11/facebook-settles-ftc-charges-it-deceived-consumers-failing-keep-privacy-promises"], ["NPR", "https://www.npr.org/sections/thetwo-way/2011/11/29/142898301/facebook-settles-with-ftc-on-charges-it-deceived-users-on-privacy"]], "slug": "2009-private-settings-made-public-without-warning", "url": "/record/2009-private-settings-made-public-without-warning/"}, {"id": "contagion", "date": "2012-01", "title": "A secret experiment on people’s moods", "tier": "admitted", "themes": ["privacy"], "summary": "For one week in January 2012, Facebook changed how much positive or negative content people saw in their feeds, then measured whether their own posts turned happier or sadder. They were not told. Facebook’s researchers published the results in 2014.", "fig": "689,003", "cap": "people in the experiment", "sources": [["The published paper (PNAS)", "https://pmc.ncbi.nlm.nih.gov/articles/PMC4066473"], ["Cornell announcement", "https://www.sciencedaily.com/releases/2014/06/140613142533.htm"]], "slug": "2012-a-secret-experiment-on-peoples-moods", "url": "/record/2012-a-secret-experiment-on-peoples-moods/"}, {"id": "outed", "date": "2012-10", "title": "Two gay students outed to their families", "tier": "reported", "themes": ["lgbtq", "privacy"], "summary": "Bobbi Duncan and Taylor McCormick at UT-Austin had set their privacy controls so their fathers would not learn they were gay. When the Queer Chorus president added them to the choir’s Facebook group, Facebook announced it to all their friends. Any user could be added to a group without approving it.", "response": "“Their unfortunate experience reminds us that we must continue our work to empower and educate users about our robust privacy controls.”", "who": "Facebook, 2012", "sources": [["PinkNews", "https://www.thepinknews.com/2012/10/16/facebook-accidentally-outed-users-to-their-parents-through-group-permissions-loophole/"], ["EDGE Media", "https://www.edgemedianetwork.com/story.php?138056"], ["Duncan on HuffPost Live", "https://www.huffpost.com/entry/outed-on-facebook_n_4563522"]], "slug": "2012-two-gay-students-outed-to-their-families", "url": "/record/2012-two-gay-students-outed-to-their-families/"}, {"id": "realname", "date": "2014-09", "title": "Drag performers and trans users locked out", "tier": "admitted", "themes": ["lgbtq"], "summary": "Facebook suspended drag performers and transgender users who did not use their legal names, after one person reported several hundred of their accounts as fake. Chief product officer Chris Cox apologized on October 1, 2014, and Facebook changed how the policy was enforced.", "response": "Cox apologized “for the hardship that we’ve put you through.”", "who": "Chris Cox, 2014", "sources": [["NPR", "https://www.npr.org/sections/alltechconsidered/2014/10/01/353053455/facebook-apologizes-for-name-policy-that-affected-lgbt-community"], ["The Register", "https://www.theregister.co.uk/2014/10/01/facebook_apologizes_for_binning_accounts_of_drag_queens/"], ["Fortune", "https://fortune.com/2014/10/01/facebook-real-name-policy-drag-queens"]], "slug": "2014-drag-performers-and-trans-users-locked-out", "url": "/record/2014-drag-performers-and-trans-users-locked-out/"}, {"id": "ira", "date": "2017-10", "title": "Russian operation reaches up to 126 million Americans", "tier": "admitted", "themes": ["democracy"], "summary": "Facebook told Congress that Russia’s Internet Research Agency published about 80,000 posts between June 2015 and August 2017, mostly on divisive subjects such as race and guns. About 29 million people were served the posts directly; sharing spread them further.", "fig": "126M", "cap": "Americans who may have been served the content, by Facebook’s own estimate", "sources": [["CNBC", "https://www.cnbc.com/2017/10/30/facebook-says-russia-backed-election-content-reached-126-million-americans.html"], ["CNN via KSHB", "https://www.kshb.com/news/national/facebook-estimates-126-million-people-were-served-content-from-russia-linked-pages"]], "slug": "2017-russian-operation-reaches-up-to-126-million-americans", "url": "/record/2017-russian-operation-reaches-up-to-126-million-americans/"}, {"id": "myanmar", "date": "2017-08", "title": "Hate against the Rohingya spreads on Facebook", "tier": "admitted", "themes": ["abroad"], "summary": "As Myanmar’s military drove more than 700,000 Rohingya into Bangladesh, UN investigators said social media, meaning Facebook in Myanmar, played a “determining role” in the hatred. A report Facebook commissioned found it had not done enough. Amnesty International concluded in 2022 that its algorithms substantially contributed.", "fig": "700,000+", "cap": "Rohingya forced to flee", "response": "“Prior to this year, we weren’t doing enough to help prevent our platform from being used to foment division and incite offline violence.”", "who": "Facebook, 2018", "status": "A US lawsuit seeking $150 billion was dismissed. The Ninth Circuit affirmed in April 2026.", "sources": [["UN investigators (Al Jazeera)", "https://www.aljazeera.com/news/2018/3/13/un-facebook-had-a-role-in-rohingya-genocide"], ["Facebook’s assessment", "https://about.fb.com/2018/11/myanmar-hria/"], ["Amnesty International", "https://www.amnesty.org/en/latest/news/2022/09/myanmar-facebooks-systems-promoted-violence-against-rohingya-meta-owes-reparations-new-report/"]], "slug": "2017-hate-against-the-rohingya-spreads-on-facebook", "url": "/record/2017-hate-against-the-rohingya-spreads-on-facebook/"}, {"id": "lynchings", "date": "2018-07", "title": "Rumors on WhatsApp precede mob killings in India", "tier": "reported", "themes": ["abroad"], "summary": "Rumors about child kidnappers spread on social media, including WhatsApp, ahead of a wave of mob attacks in India. In every case IndiaSpend reviewed, no evidence of kidnapping was found. In July 2018 WhatsApp began labeling forwarded messages and limited forwarding in India to five chats at once.", "fig": "33", "cap": "people killed in 69 attacks, January 2017 to July 2018, by IndiaSpend’s count", "sources": [["IndiaSpend (via BOOM)", "https://www.boomlive.in/child-lifting-rumours-33-killed-in-69-mob-attacks-since-jan-2017-before-that-only-1-attack-in-2012"], ["Al Jazeera", "https://www.aljazeera.com/amp/news/2018/7/20/whatsapp-curbs-india-services-after-spate-of-lynchings"], ["Fortune", "https://fortune.com/2018/07/20/whatsapp-forwarding-india-lynchings"]], "slug": "2018-rumors-on-whatsapp-precede-mob-killings-in-india", "url": "/record/2018-rumors-on-whatsapp-precede-mob-killings-in-india/"}, {"id": "srilanka", "date": "2018-03", "title": "Anti-Muslim riots in Sri Lanka", "tier": "admitted", "themes": ["abroad"], "summary": "Rumors and hate speech spread on Facebook ahead of riots in which mosques and Muslim-owned businesses burned and at least three people died. Officials said Facebook had only two people reviewing Sinhala content. The assessment Facebook commissioned found posts may have led to offline violence.", "fig": "2", "cap": "Sinhala-language reviewers, according to officials", "response": "“We recognize, and apologize for, the very real human rights impacts that resulted.”", "who": "Facebook, 2020", "sources": [["Al Jazeera", "https://www.aljazeera.com/news/2020/5/13/sri-lanka-facebook-apologises-for-role-in-2018-anti-muslim-riots"]], "slug": "2018-anti-muslim-riots-in-sri-lanka", "url": "/record/2018-anti-muslim-riots-in-sri-lanka/"}, {"id": "ca", "date": "2018-03", "title": "Cambridge Analytica", "tier": "settled", "themes": ["privacy", "democracy"], "summary": "A researcher’s quiz app harvested data from up to 87 million users, most of them friends of the people who took the quiz, and passed it to a political consulting firm. Facebook learned of it in 2015, asked for the data to be deleted, and considered the matter closed until news reports in 2018.", "fig": "$5.8B", "cap": "FTC $5B, SEC $100M and a $725M class action", "response": "Meta settled the class action without admitting wrongdoing.", "status": "The class settlement became final in May 2025. In September 2026, a New Mexico jury found Meta’s promises after the scandal willfully misleading.", "sources": [["Clifford Chance on the FTC penalty", "https://www.cliffordchance.com/briefings/2019/08/ftc_s_5_billion_penaltyagainstfacebook.html"], ["Bloomberg Law on the $725M settlement", "https://news.bloomberglaw.com/esg/meta-agrees-to-pay-725-million-over-cambridge-analytica-scandal"]], "photo": {"src": "/img/wylie-parliament-2018.jpg", "w": 1600, "h": 900, "alt": "Christopher Wylie, with pink hair, speaks into a megaphone at a dusk protest in Parliament Square, London. People hold signs reading “Fair Vote” behind him.", "caption": "Christopher Wylie, a former Cambridge Analytica employee turned whistleblower, at a protest in Parliament Square, London, on March 29, 2018.", "credit": "Photo: Jwslubbock, Wikimedia Commons, CC BY-SA 4.0", "license": "https://creativecommons.org/licenses/by-sa/4.0/", "source": "https://commons.wikimedia.org/wiki/File:Cambridge_Analytica_protest_Parliament_Square2.jpg"}, "slug": "2018-cambridge-analytica", "url": "/record/2018-cambridge-analytica/"}, {"id": "viewas", "date": "2018-09", "title": "“View As” breach exposes 29 million accounts", "tier": "appeal", "themes": ["privacy"], "summary": "Attackers chained three bugs in the “View As” feature to steal login tokens. Exposed data included names, contact details, locations, workplaces, religion and posts. In December 2024 Ireland’s regulator fined Meta for failing to build in data protection and for gaps in how it reported the breach.", "fig": "€251M", "cap": "fine, December 2024; about 29 million accounts affected", "sources": [["The Register", "https://www.theregister.com/2024/12/17/ireland_fines_meta_for_2018/"], ["Security Affairs", "https://securityaffairs.com/172100/laws-and-regulations/dpc-fined-meta-e251-million.html"], ["Bloomberg via BNN", "https://bnnbloomberg.ca/business/company-news/2024/12/17/metas-irish-arm-fined-251-million-by-watchdog-over-data-breach"]], "status": "Meta said it will appeal.", "slug": "2018-view-as-breach-exposes-29-million-accounts", "url": "/record/2018-view-as-breach-exposes-29-million-accounts/"}, {"id": "atlas", "date": "2019-01", "title": "Teenagers paid for access to their phones", "tier": "reported", "themes": ["kids", "privacy"], "summary": "Since 2016, Facebook had paid people aged 13 to 35 up to $20 a month in gift cards to install a “Research” app with root access to their phone traffic. Some minors only had to tick a box claiming parental consent. Facebook ended the program on iPhone after TechCrunch reported it.", "fig": "$20", "cap": "a month, in gift cards", "response": "“There was nothing ‘secret’ about this; it was literally called the Facebook Research App.”", "who": "Facebook, 2019", "sources": [["TechCrunch", "https://techcrunch.com/2019/02/28/facebook-research-teens/"], ["NPR", "https://www.npr.org/2019/01/30/690172103/facebook-google-draw-scrutiny-over-apps-that-collected-data-from-teens"]], "slug": "2019-teenagers-paid-for-access-to-their-phones", "url": "/record/2019-teenagers-paid-for-access-to-their-phones/"}, {"id": "housing", "date": "2019-03", "title": "Housing ads steered by race and sex", "tier": "settled", "themes": ["rights"], "summary": "The US housing department charged that Facebook’s ad system let advertisers target and exclude people by protected traits and delivered housing ads in discriminatory ways. In a 2022 settlement with the Justice Department, Meta retired a targeting tool and paid the largest penalty the Fair Housing Act allows.", "fig": "$115,054", "cap": "the maximum Fair Housing Act penalty", "sources": [["HousingWire", "https://www.housingwire.com/articles/meta-to-settle-with-doj-over-fair-housing-act-claims/"], ["JURIST", "https://www.jurist.org/news/2022/06/us-doj-reaches-settlement-with-meta-platforms-over-discriminatory-advertising-claims"]], "slug": "2019-housing-ads-steered-by-race-and-sex", "url": "/record/2019-housing-ads-steered-by-race-and-sex/"}, {"id": "modsus", "date": "2020-05", "title": "Moderators with PTSD win $52 million", "tier": "settled", "themes": ["labor"], "summary": "Contract moderators who spent their shifts reviewing rape, murder and suicide footage sued after developing PTSD. The settlement covered moderators in four states and required counseling and tools such as muted audio by default.", "fig": "$52M", "cap": "for 11,250 moderators", "sources": [["KUOW / NPR", "https://www.kuow.org/stories/in-settlement-facebook-to-pay-52-million-to-content-moderators-with-ptsd"]], "slug": "2020-moderators-with-ptsd-win-52-million", "url": "/record/2020-moderators-with-ptsd-win-52-million/"}, {"id": "illinois", "date": "2021-02", "title": "Illinois users win $650 million over face scans", "tier": "settled", "themes": ["privacy"], "summary": "Facebook’s “tag suggestions” feature ran facial recognition on users’ photos by default from 2011. Illinois users sued under the state’s biometric privacy law.", "fig": "$650M", "cap": "class settlement", "sources": [["Fortune", "https://fortune.com/2024/07/30/meta-texas-privacy-lawsuit-settlement-mark-zuckerberg-facebook-facial-recognition"]], "slug": "2021-illinois-users-win-650-million-over-face-scans", "url": "/record/2021-illinois-users-win-650-million-over-face-scans/"}, {"id": "scrape", "date": "2021-04", "title": "533 million users’ phone numbers posted online", "tier": "appeal", "themes": ["privacy"], "summary": "Scrapers abused Facebook’s contact-import tools to collect names, phone numbers, birthdates and locations from users in 106 countries, then posted the set on a hacking forum. Ireland’s regulator found Meta had not built in adequate protection.", "fig": "€265M", "cap": "fine from Ireland’s Data Protection Commission, 2022", "status": "Meta challenged the fine in Ireland’s High Court.", "sources": [["The Irish Times", "https://www.irishtimes.com/business/2023/03/27/meta-challenges-dpcs-265-million-fine-over-third-party-data-scrape/"], ["Associated Press", "https://www.clickorlando.com/business/2022/11/28/irish-watchdog-fines-meta-265m-euros-in-latest-privacy-case/"]], "slug": "2021-533-million-users-phone-numbers-posted-online", "url": "/record/2021-533-million-users-phone-numbers-posted-online/"}, {"id": "wa225", "date": "2021-09", "title": "WhatsApp fined over how it explained data sharing", "tier": "ruled", "themes": ["privacy"], "summary": "Ireland’s regulator found WhatsApp broke EU rules in how it explained sharing people’s data with other Meta companies.", "fig": "€225M", "cap": "fine", "sources": [["Deccan Herald / AP", "https://www.deccanherald.com/business/irish-watchdog-fines-meta-265-million-euros-in-latest-privacy-case-1166531.html"]], "slug": "2021-whatsapp-fined-over-how-it-explained-data-sharing", "url": "/record/2021-whatsapp-fined-over-how-it-explained-data-sharing/"}, {"id": "teens", "date": "2021-09", "title": "Meta’s own research on teen girls leaks", "tier": "reported", "themes": ["kids"], "summary": "Internal slides said Instagram made body-image issues worse for one in three teen girls who already had them. Among teens who reported suicidal thoughts, 13% of British and 6% of American users traced them to Instagram.", "fig": "32%", "cap": "of teen girls who felt bad about their bodies said Instagram made it worse", "response": "Meta said the reporting mischaracterized research that, in some cases, relied on input from 40 teens.", "sources": [["ABC News summary", "https://abc7news.com/facebook-knows-instagram-is-toxic-for-teen-girls-mental-health-teenage-body-image-issues/11022272/"], ["The Facebook Papers archive (Gizmodo)", "https://gizmodo.com/facebook-papers-how-to-read-1848702919"]], "photo": {"src": "/img/haugen-testimony-2021.jpg", "w": 956, "h": 885, "alt": "Frances Haugen at the witness table in a Senate hearing room, looking down at her notes, a microphone in front of her.", "caption": "Frances Haugen testifies to a Senate Commerce subcommittee on October 5, 2021.", "credit": "Image: U.S. Senate Committee on Commerce, Science, and Transportation, public domain", "source": "https://commons.wikimedia.org/wiki/File:Frances_Haugen_testimony.png"}, "slug": "2021-metas-own-research-on-teen-girls-leaks", "url": "/record/2021-metas-own-research-on-teen-girls-leaks/"}, {"id": "amare", "date": "2021-11", "title": "A professor is killed after posts target him", "tier": "alleged", "themes": ["abroad"], "summary": "Professor Meareg Amare Abrha was killed in Bahir Dar during Ethiopia’s civil war. His son alleges that Facebook posts doxxed him and called for violence, and that Meta did not respond to reports until after his death.", "fig": "$1.6B", "cap": "victims’ fund sought when the case was filed; later filings seek more", "status": "Kenya’s High Court ruled in April 2025 that it can hear the case. The claims have not been tried.", "sources": [["CNBC Africa / Reuters", "https://cnbc.africa/2025/meta-can-be-sued-in-kenya-over-posts-related-to-ethiopia-violence-court-rules"], ["Amnesty International", "https://www.amnesty.org/en/latest/news/2024/09/kenya-high-court-to-decide-jurisdiction-of-landmark-meta-case/"]], "slug": "2021-a-professor-is-killed-after-posts-target-him", "url": "/record/2021-a-professor-is-killed-after-posts-target-him/"}, {"id": "nebraska", "date": "2022-06", "title": "Private messages used in an abortion prosecution", "tier": "reported", "themes": ["privacy"], "summary": "Nebraska police served Meta a warrant for Messenger chats between a mother and her 17-year-old daughter, and the messages became evidence. The mother later pleaded guilty. Meta complied with a valid warrant. The chats were readable because Messenger did not encrypt them by default at the time.", "response": "Meta said the warrants “did not mention abortion at all.”", "sources": [["NPR", "https://www.npr.org/2022/08/12/1117092169/nebraska-cops-used-facebook-messages-to-investigate-an-alleged-illegal-abortion"], ["The Register", "https://www.theregister.com/2023/07/11/mother_abortion_meta/"]], "slug": "2022-private-messages-used-in-an-abortion-prosecution", "url": "/record/2022-private-messages-used-in-an-abortion-prosecution/"}, {"id": "pixel", "date": "2022-06", "title": "Tracking code on hospital websites", "tier": "reported", "themes": ["privacy"], "summary": "The Markup found the Meta Pixel on the websites of 33 of Newsweek’s top 100 US hospitals, sending Facebook a packet of data when people booked appointments. Inside the patient portals of seven health systems, it sent details such as medications and conditions. Several hospitals removed it after the report.", "status": "Class-action lawsuits over the Pixel on health sites are pending.", "sources": [["STAT and The Markup", "https://www.statnews.com/2022/06/16/facebook-meta-pixel-hospitals-data/"], ["The Markup", "https://themarkup.org/inside-the-markup/2023/02/22/the-markup-honored-by-ahcj-awards-for-excellence-in-health-care-journalism"], ["Becker’s Hospital Review", "https://www.beckershospitalreview.com/healthcare-information-technology/some-hospital-websites-are-sending-sensitive-patient-data-to-facebook-report-says/"]], "fig": "33 of 100", "cap": "top US hospitals with the Pixel on their sites", "slug": "2022-tracking-code-on-hospital-websites", "url": "/record/2022-tracking-code-on-hospital-websites/"}, {"id": "ig405", "date": "2022-09", "title": "Instagram exposed teenagers’ contact details", "tier": "appeal", "themes": ["kids", "privacy"], "summary": "Ireland’s regulator fined Instagram over business-account settings that made teenagers’ phone numbers and email addresses public.", "fig": "€405M", "cap": "fine", "status": "Meta sought judicial review in Ireland.", "sources": [["The Irish Times", "https://www.irishtimes.com/business/2023/03/27/meta-challenges-dpcs-265-million-fine-over-third-party-data-scrape/"]], "slug": "2022-instagram-exposed-teenagers-contact-details", "url": "/record/2022-instagram-exposed-teenagers-contact-details/"}, {"id": "basis", "date": "2023-01", "title": "Fined for forcing users into personalized ads", "tier": "appeal", "themes": ["privacy"], "summary": "Ireland’s regulator found Meta relied on the wrong legal basis to process personal data for behavioral advertising on Facebook and Instagram.", "fig": "€390M", "cap": "fines for Facebook and Instagram", "sources": [["Deccan Herald / AFP", "https://www.deccanherald.com/business/meta-fined-390-million-by-eu-over-data-breaches-1177939.html"]], "slug": "2023-fined-for-forcing-users-into-personalized-ads", "url": "/record/2023-fined-for-forcing-users-into-personalized-ads/"}, {"id": "mena", "date": "2023-02", "title": "Police use fake profiles to entrap LGBT people", "tier": "reported", "themes": ["lgbtq", "abroad"], "summary": "Human Rights Watch documented security forces in Egypt, Iraq and Jordan creating fake profiles on Grindr and Facebook to trap LGBT people, leading to arrests, abuse and extortion. HRW has pressed Meta on how its platforms respond to this targeting.", "fig": "20", "cap": "entrapment cases documented", "sources": [["Human Rights Watch", "https://www.hrw.org/news/2023/02/21/middle-east-north-africa-digital-targeting-lgbt-people"], ["HRW questions for Meta", "https://www.hrw.org/news/2024/01/23/questions-and-answers-facebook-instagram-and-digital-targeting-lgbt-people-mena"]], "slug": "2023-police-use-fake-profiles-to-entrap-lgbt-people", "url": "/record/2023-police-use-fake-profiles-to-entrap-lgbt-people/"}, {"id": "transfers", "date": "2023-05", "title": "Record GDPR fine over data transfers to the US", "tier": "appeal", "themes": ["privacy"], "summary": "Ireland’s regulator ruled that Meta kept moving Europeans’ Facebook data to the US without adequate protection from US surveillance, and ordered the transfers stopped.", "fig": "€1.2B", "cap": "the largest GDPR fine when it was issued", "sources": [["Stephenson Harwood", "https://www.stephensonharwood.com/insights/breaking-news-meta-receives-largest-gdpr-fine-to-date/"]], "slug": "2023-record-gdpr-fine-over-data-transfers-to-the-us", "url": "/record/2023-record-gdpr-fine-over-data-transfers-to-the-us/"}, {"id": "kenyamods", "date": "2023-06", "title": "Nairobi moderators take Meta to court", "tier": "alleged", "themes": ["labor", "abroad"], "summary": "Moderators hired through the contractor Sama reviewed graphic content for Meta. After mass layoffs, 184 of them sued, alleging trauma, unlawful dismissal and retaliation for organizing. A Kenyan court held that Meta was their principal employer, and an appeals court confirmed in 2024 that Meta can be sued in Kenya.", "fig": "184", "cap": "moderators in the case", "status": "Rulings were postponed in February 2026. The case is unresolved.", "sources": [["Business & Human Rights Resource Centre", "https://www.business-humanrights.org/en/latest-news/kenya-court-postpones-ruling-in-two-cases-against-meta-brought-by-former-content-moderators-delaying-trial-2/"], ["Computer Weekly", "https://www.computerweekly.com/feature/Kenyan-workers-win-High-Court-appeal-to-take-Meta-to-trial"]], "slug": "2023-nairobi-moderators-take-meta-to-court", "url": "/record/2023-nairobi-moderators-take-meta-to-court/"}, {"id": "canada", "date": "2023-08", "title": "News blocked in Canada during wildfire evacuations", "tier": "admitted", "themes": ["democracy"], "summary": "Meta began blocking news on Facebook and Instagram in Canada on August 1, 2023, in response to the Online News Act. When wildfires forced the evacuation of Yellowknife weeks later, the city told residents it could not share news links on Facebook, and Meta refused requests from officials and broadcasters to lift the block.", "sources": [["Associated Press (ADN)", "https://www.adn.com/nation-world/2023/08/18/as-wildfires-spread-canadian-leaders-ask-meta-to-reverse-its-news-ban/"], ["Al Jazeera", "https://www.aljazeera.com/news/2023/8/29/stupid-and-dangerous-metas-news-ban-fuels-anger-amid-canada-wildfires"]], "fig": "20,000", "cap": "Yellowknife residents ordered to evacuate", "slug": "2023-news-blocked-in-canada-during-wildfire-evacuations", "url": "/record/2023-news-blocked-in-canada-during-wildfire-evacuations/"}, {"id": "bejar", "date": "2023-11", "title": "A former safety chief testifies about unwanted advances on teens", "tier": "reported", "themes": ["kids"], "summary": "Arturo Béjar, who led Facebook’s user-safety work and later consulted for Instagram, told the Senate that Meta’s own user surveys found 13% of Instagram users aged 13 to 15 had received unwanted sexual advances in the previous seven days. He said his 2021 warnings to Zuckerberg went unanswered.", "fig": "13%", "cap": "of users aged 13 to 15, in a single week, in Meta’s own survey", "sources": [["Béjar’s written testimony", "https://www.judiciary.senate.gov/download/2023-11-07-testimony-bejar?download=1"], ["Associated Press (Fortune)", "https://www.fortune.com/2023/11/07/facebook-instagram-harmful-effects-children-mark-zuckerberg-email-contractor-congress/"]], "response": "Meta said “countless people inside and outside of Meta” work to keep young people safe online.", "slug": "2023-a-former-safety-chief-testifies-about-unwanted-advances-on-teens", "url": "/record/2023-a-former-safety-chief-testifies-about-unwanted-advances-on-teens/"}, {"id": "texas", "date": "2024-07", "title": "Texas wins $1.4 billion over face scans", "tier": "settled", "themes": ["privacy"], "summary": "Texas sued under its biometric privacy law over facial recognition that was switched on by default. Texas says it is the largest privacy settlement ever won by a single state.", "fig": "$1.4B", "cap": "settlement", "response": "Meta did not admit wrongdoing.", "sources": [["Fortune / AP", "https://fortune.com/2024/07/30/meta-texas-privacy-lawsuit-settlement-mark-zuckerberg-facebook-facial-recognition"], ["San José Inside", "https://www.sanjoseinside.com/business/meta-reaches-1-4b-settlement-with-texas-over-privacy-violations/"]], "slug": "2024-texas-wins-1-4-billion-over-face-scans", "url": "/record/2024-texas-wins-1-4-billion-over-face-scans/"}, {"id": "nigeria", "date": "2024-07", "title": "Nigeria fines Meta and WhatsApp $220 million", "tier": "ruled", "themes": ["privacy", "market"], "summary": "After a 38-month investigation, Nigeria’s consumer protection regulator found WhatsApp’s 2021 data policy broke Nigerian consumer and data protection law. A tribunal upheld the fine in April 2025.", "fig": "$220M", "cap": "fine, plus costs", "response": "“We disagree with both this decision and the fine and will appeal.”", "who": "Meta, 2024", "sources": [["Nigeria FCCPC", "https://fccpc.gov.ng/violations-tribunal-upholds-fccpcs-220-million-fine-against-meta-whatsapp/"]], "slug": "2024-nigeria-fines-meta-and-whatsapp-220-million", "url": "/record/2024-nigeria-fines-meta-and-whatsapp-220-million/"}, {"id": "crowdtangle", "date": "2024-08", "title": "Meta shuts down the CrowdTangle research tool", "tier": "reported", "themes": ["democracy"], "summary": "Meta shut down CrowdTangle, the free tool journalists and researchers used to track how content spread, on August 14, 2024. Dozens of groups had asked it to keep the tool running through the US election, and the European Commission demanded answers under the Digital Services Act. Its replacement is limited to academic and nonprofit researchers.", "sources": [["Associated Press (Las Vegas Sun)", "https://lasvegassun.com/news/2024/aug/14/meta-kills-off-misinformation-tracking-tool-crowdt/"], ["Columbia Journalism Review", "https://cjr.org/tow_center/meta-is-getting-rid-of-crowdtangle.php"], ["Fortune", "https://www.fortune.com/europe/2024/08/16/meta-pulled-its-disinformation-tracker-from-facebook-months-before-america-heads-to-the-polls-and-the-eu-isnt-happy/"]], "response": "Meta said its replacement, the Meta Content Library, was built to meet new regulatory requirements while protecting privacy.", "slug": "2024-meta-shuts-down-the-crowdtangle-research-tool", "url": "/record/2024-meta-shuts-down-the-crowdtangle-research-tool/"}, {"id": "marketplace", "date": "2024-11", "title": "EU fines Meta for tying Marketplace to Facebook", "tier": "appeal", "themes": ["market"], "summary": "The European Commission found Meta dominant in social networking and ruled it abused that position by tying Facebook Marketplace to Facebook and by imposing unfair terms on rival classified-ad services that advertise on its platforms.", "fig": "€797.72M", "cap": "fine", "sources": [["TechCrunch", "https://techcrunch.com/2024/11/14/meta-slapped-with-a-e798m-fine-in-europe-its-biggest-yet"], ["Society for Computers and Law", "https://www.scl.org/european-commission-fines-meta-e797-72-million-over-abusive-practices-benefitting-facebook-marketplace/"]], "status": "Meta said it will appeal.", "slug": "2024-eu-fines-meta-for-tying-marketplace-to-facebook", "url": "/record/2024-eu-fines-meta-for-tying-marketplace-to-facebook/"}, {"id": "korea", "date": "2024-11", "title": "Religion and sexuality turned into ad categories", "tier": "ruled", "themes": ["lgbtq", "privacy"], "summary": "South Korea’s privacy regulator found Meta analyzed pages users liked and ads they clicked to build ad categories on religion, political views, same-sex relationships and North Korean defector status for about 980,000 Korean Facebook users, and made them available to about 4,000 advertisers without proper consent.", "fig": "₩21.6B", "cap": "about $15.7 million", "sources": [["The Record", "https://therecord.media/facebook-south-korea-privacy-regulator-fine"], ["The Hacker News", "https://thehackernews.com/2024/11/south-korea-fines-meta-1567m-for.html"]], "slug": "2024-religion-and-sexuality-turned-into-ad-categories", "url": "/record/2024-religion-and-sexuality-turned-into-ad-categories/"}, {"id": "india", "date": "2024-11", "title": "India penalizes WhatsApp’s take-it-or-leave-it policy", "tier": "appeal", "themes": ["market", "privacy"], "summary": "India’s competition regulator found WhatsApp’s 2021 policy forced users to accept data sharing with Meta. An appeals tribunal upheld the penalty in November 2025.", "fig": "₹213 crore", "cap": "about $25 million", "status": "Meta has appealed to India’s Supreme Court.", "sources": [["Business Standard", "https://www.business-standard.com/industry/news/nclat-sets-aside-cci-data-sharing-ban-upholds-meta-penalty-2025-125110401578_1.html"]], "slug": "2024-india-penalizes-whatsapps-take-it-or-leave-it-policy", "url": "/record/2024-india-penalizes-whatsapps-take-it-or-leave-it-policy/"}, {"id": "hateful", "date": "2025-01", "title": "Calling LGBTQ+ people mentally ill is now allowed", "tier": "admitted", "themes": ["lgbtq", "democracy"], "summary": "Meta rewrote its hateful conduct rules and ended third-party fact-checking in the US. The new rules allow posts calling LGBTQ+ people mentally ill or abnormal, and dropped the ban on referring to transgender people as “it.”", "response": "The policy now allows “allegations of mental illness or abnormality when based on gender or sexual orientation.”", "who": "Meta’s Community Standards", "sources": [["WLRN / PolitiFact", "https://www.wlrn.org/government-politics/2025-01-14/meta-permits-calling-lgbtq-mentally-ill"], ["Electronic Frontier Foundation", "https://eff.org/deeplinks/2025/01/metas-new-content-policy-will-harm-vulnerable-users-if-it-really-valued-free"]], "slug": "2025-calling-lgbtq-people-mentally-ill-is-now-allowed", "url": "/record/2025-calling-lgbtq-people-mentally-ill-is-now-allowed/"}, {"id": "careless", "date": "2025-03", "title": "A former executive’s memoir alleges help for China’s censors", "tier": "alleged", "themes": ["democracy"], "summary": "In Careless People, former public policy director Sarah Wynn-Williams alleges Meta built censorship tools while courting the Chinese market. An emergency arbitrator, citing her severance agreement’s non-disparagement clause, barred her from promoting the book. The order did not address whether her claims were true.", "response": "Meta called the book “false and defamatory.”", "sources": [["KQED", "https://www.kqed.org/arts/13973446/facebook-book-memoir-careless-people-sales"], ["NBC News", "https://www.nbcnewyork.com/news/business/money-report/meta-goes-to-arbitrator-to-prevent-whistleblower-from-promoting-tell-all-book/6184798/"]], "slug": "2025-a-former-executives-memoir-alleges-help-for-chinas-censors", "url": "/record/2025-a-former-executives-memoir-alleges-help-for-chinas-censors/"}, {"id": "dma", "date": "2025-04", "title": "“Pay or consent” breaks Europe’s digital markets law", "tier": "appeal", "themes": ["privacy", "market"], "summary": "The European Commission found that making users either pay for ad-free Facebook and Instagram or consent to tracking did not offer a real option to share less data.", "fig": "€200M", "cap": "fine", "sources": [["European Commission", "https://digital-strategy.ec.europa.eu/en/news/commission-finds-apple-and-meta-breach-digital-markets-act"]], "slug": "2025-pay-or-consent-breaks-europes-digital-markets-law", "url": "/record/2025-pay-or-consent-breaks-europes-digital-markets-law/"}, {"id": "localmess", "date": "2025-06", "title": "Hidden tracking tied private browsing to accounts", "tier": "reported", "themes": ["privacy"], "summary": "Researchers found the Meta Pixel, embedded on millions of websites, passed browsing identifiers to the Facebook and Instagram apps on Android. For people logged into those apps, that linked their web browsing, including in incognito mode, to their accounts. Meta had used the method since September 2024 and stopped when the research was published.", "fig": "5.8M+", "cap": "websites carrying the Meta Pixel", "response": "Meta said it decided “to pause the feature while we work with Google to resolve the issue.”", "sources": [["IMDEA Networks", "https://networks.imdea.org/research-co-led-by-imdea-networks-discovers-a-privacy-abuse-involving-meta-and-yandex-bridging-persistent-identifiers-to-browsing-histories/"], ["The Register", "https://www.theregister.com/2025/06/03/meta_pauses_android_tracking_tech/"]], "slug": "2025-hidden-tracking-tied-private-browsing-to-accounts", "url": "/record/2025-hidden-tracking-tied-private-browsing-to-accounts/"}, {"id": "flo", "date": "2025-08", "title": "Jury finds Meta eavesdropped on period-tracker users", "tier": "ruled", "themes": ["privacy"], "summary": "Users of the Flo app entered details about their periods, pregnancies and sexual activity after being promised privacy. A federal jury found Meta intentionally recorded that data through code embedded in the app, violating California’s wiretapping law. The other defendants settled before trial.", "response": "“The plaintiffs’ claims against Meta are simply false.”", "who": "Meta, 2025", "status": "Liability found August 1, 2025. Damages have not been set.", "sources": [["National Law Review via Darrow", "https://www.darrow.ai/news/jury-finds-meta-liable-for-collecting-private-reproductive-health-data"], ["Data Privacy + Security Insider", "https://www.dataprivacyandsecurityinsider.com/2025/08/federal-jury-finds-against-meta-for-collecting-data-from-flo-health/"]], "slug": "2025-jury-finds-meta-eavesdropped-on-period-tracker-users", "url": "/record/2025-jury-finds-meta-eavesdropped-on-period-tracker-users/"}, {"id": "airules", "date": "2025-08", "title": "AI chatbots allowed romantic talk with children", "tier": "admitted", "themes": ["kids"], "summary": "Reuters obtained Meta’s internal rules for its AI chatbots, approved by legal, policy and engineering staff including its chief ethicist. They permitted the bots to engage children in romantic or sensual conversations. Meta confirmed the document and removed those sections after Reuters asked about them.", "response": "Meta said the examples were “erroneous and inconsistent with our policies.”", "sources": [["TechCrunch", "https://techcrunch.com/2025/08/14/leaked-meta-ai-rules-show-chatbots-were-allowed-to-have-romantic-chats-with-kids/"]], "slug": "2025-ai-chatbots-allowed-romantic-talk-with-children", "url": "/record/2025-ai-chatbots-allowed-romantic-talk-with-children/"}, {"id": "vr", "date": "2025-09", "title": "Former researchers say VR child-safety work was buried", "tier": "alleged", "themes": ["kids"], "summary": "Former Meta researchers Jason Sattizahn and Cayce Savage told the Senate that children on Meta’s VR platforms faced sexual solicitation and harassment, and that the company had them erase or change research documenting it. Six current and former researchers made similar allegations.", "response": "Meta called the allegations a “predetermined and false narrative.”", "sources": [["Roll Call", "https://rollcall.com/2025/09/09/whistleblowers-tell-senate-panel-meta-hid-vr-harms/"], ["AFP (Inquirer)", "https://technology.inquirer.net/143056/former-meta-researchers-testify-company-buried-child-safety-studies/amp"]], "slug": "2025-former-researchers-say-vr-child-safety-work-was-buried", "url": "/record/2025-former-researchers-say-vr-child-safety-work-was-buried/"}, {"id": "scams", "date": "2025-11", "title": "Internal documents project $16 billion from scam and banned-goods ads", "tier": "reported", "themes": ["scams"], "summary": "Reuters reported that Meta projected about 10% of its 2024 revenue would come from ads for scams and banned goods, and that it banned advertisers only when it was 95% certain of fraud. The reporting won a Pulitzer Prize.", "fig": "~$16B", "cap": "projected, 2024", "response": "Meta called the 10% figure an overly inclusive estimate and says it removed 159 million scam ads in 2025.", "sources": [["Lawfare", "https://www.lawfaremedia.org/article/reuters-blows-lid-on-meta's-fraud-profit-scandal"], ["The Pulitzer Prizes", "https://www.pulitzer.org/winners/jeff-horwitz-and-engen-tham-reuters"], ["The Record", "https://therecord.media/meta-scam-advertising-crackdown"]], "slug": "2025-internal-documents-project-16-billion-from-scam-and-banned-goods", "url": "/record/2025-internal-documents-project-16-billion-from-scam-and-banned-goods/"}, {"id": "antitrust", "date": "2025-11", "title": "The FTC loses its case to break up Meta", "tier": "dismissed", "themes": ["market"], "summary": "The FTC argued Meta bought Instagram and WhatsApp to neutralize rivals, citing a 2008 Zuckerberg email saying it is better to buy than compete. The judge ruled the FTC had not shown Meta holds monopoly power today, largely because of competition from TikTok and YouTube.", "sources": [["Wikipedia", "https://en.wikipedia.org/wiki/FTC_v._Meta"], ["Sullivan & Cromwell", "https://www.sullcrom.com/insights/memo/2025/December/Meta-Prevails-FTC-Monopolization-Case"]], "slug": "2025-the-ftc-loses-its-case-to-break-up-meta", "url": "/record/2025-the-ftc-loses-its-case-to-break-up-meta/"}, {"id": "kgm", "date": "2026-03", "title": "Jury finds Instagram’s design harmed a young user", "tier": "appeal", "themes": ["kids"], "summary": "A Los Angeles jury found Meta and YouTube negligent in designing platforms that a young woman used compulsively from childhood, contributing to her depression and anxiety. The jury assigned Meta 70% of the responsibility.", "fig": "$6M", "cap": "total damages; Meta’s share about $4.2 million", "response": "Meta said teen mental health is complex and cannot be linked to a single app.", "sources": [["NPR", "https://www.npr.org/2026/03/25/nx-s1-5746125/meta-youtube-social-media-trial-verdict"]], "slug": "2026-jury-finds-instagrams-design-harmed-a-young-user", "url": "/record/2026-jury-finds-instagrams-design-harmed-a-young-user/"}, {"id": "nm1", "date": "2026-03", "title": "New Mexico jury: Meta misled families about predators", "tier": "appeal", "themes": ["kids"], "summary": "State investigators posing as children on Facebook and Instagram were shown sexual content and solicited by adults. The jury found Meta violated New Mexico’s consumer protection law and imposed the maximum penalty for each violation.", "fig": "$375M", "cap": "civil penalties", "sources": [["New Mexico Department of Justice", "https://nmdoj.gov/press-release/new-mexico-department-of-justice-wins-landmark-verdict-against-meta/"]], "slug": "2026-new-mexico-jury-meta-misled-families-about-predators", "url": "/record/2026-new-mexico-jury-meta-misled-families-about-predators/"}, {"id": "rohingya9", "date": "2026-04", "title": "Appeals court upholds dismissal of Rohingya lawsuit", "tier": "dismissed", "themes": ["abroad"], "summary": "The Ninth Circuit affirmed the dismissal of the Rohingya refugees’ class action, holding that Section 230 shields Meta from liability for the posts.", "sources": [["Ninth Circuit opinion", "https://cdn.ca9.uscourts.gov/datastore/opinions/2026/04/28/24-1672.pdf"]], "slug": "2026-appeals-court-upholds-dismissal-of-rohingya-lawsuit", "url": "/record/2026-appeals-court-upholds-dismissal-of-rohingya-lawsuit/"}, {"id": "glaad", "date": "2026-05", "title": "Meta’s LGBTQ+ safety scores fall again", "tier": "reported", "themes": ["lgbtq"], "summary": "GLAAD’s Social Media Safety Index scored Instagram 41, Facebook 40 and Threads 39 out of 100, down from 45, 45 and 40 the year before.", "fig": "40/100", "cap": "Facebook’s score", "sources": [["GLAAD", "https://glaad.org/smsi/2026/meta-platforms/"]], "slug": "2026-metas-lgbtq-safety-scores-fall-again", "url": "/record/2026-metas-lgbtq-safety-scores-fall-again/"}, {"id": "dsa", "date": "2026-07", "title": "EU says addictive design breaks the Digital Services Act", "tier": "alleged", "themes": ["kids"], "summary": "In preliminary findings, the European Commission said Meta did not adequately assess the risks of Instagram’s and Facebook’s addictive design to users’ well-being, including minors’.", "response": "“We disagree.”", "who": "Meta", "status": "Preliminary. A final decision could carry fines of up to 6% of global turnover.", "sources": [["CNBC", "https://www.cnbc.com/2026/07/10/meta-instagram-facebook-addictive-design-breach-eu-laws.html"]], "slug": "2026-eu-says-addictive-design-breaks-the-digital-services-act", "url": "/record/2026-eu-says-addictive-design-breaks-the-digital-services-act/"}, {"id": "nm2", "date": "2026-08", "title": "Judge declares Meta a public nuisance", "tier": "appeal", "themes": ["kids"], "summary": "A New Mexico judge ordered a $567 million fund for treatment, screening and prevention, and changes for minors: like counts hidden by default, notifications paused overnight, and no romantic AI chats.", "fig": "$942M", "cap": "total with the jury penalty", "sources": [["New Mexico Department of Justice", "https://nmdoj.gov/press-release/court-orders-meta-to-pay-942-million-and-overhaul-protections-for-children-on-facebook-and-instagram-in-landmark-new-mexico-ruling/"], ["TechCrunch", "https://techcrunch.com/2026/08/07/new-mexico-court-orders-meta-to-pay-additional-567m-in-child-safety-case/"]], "slug": "2026-judge-declares-meta-a-public-nuisance", "url": "/record/2026-judge-declares-meta-a-public-nuisance/"}, {"id": "multistate", "date": "2026-08", "title": "State attorneys general settle for at least $12.1 billion", "tier": "settled", "themes": ["kids"], "summary": "State attorneys general who sued in 2023 settled in the middle of trial. Meta agreed to hard daily time limits for teens, an independent auditor and a ban on deceptive safety claims.", "fig": "$12.1B+", "cap": "over ten years, rising to $17.1B if other conditions are met", "response": "Meta denied the allegations and admitted no wrongdoing.", "sources": [["DC Attorney General", "https://oag.dc.gov/release/attorney-general-schwalb-announces-meta-will-pay"], ["PBS NewsHour", "https://www.pbs.org/newshour/nation/meta-reaches-17-billion-settlement-with-states-in-landmark-trial-over-teen-social-media-addiction"]], "slug": "2026-state-attorneys-general-settle-for-at-least-12-1-billion", "url": "/record/2026-state-attorneys-general-settle-for-at-least-12-1-billion/"}, {"id": "nm3", "date": "2026-09", "title": "A second jury finds 43.9 million deceptions", "tier": "ruled", "themes": ["privacy", "democracy"], "summary": "In a case New Mexico filed in 2021 over Cambridge Analytica, a Santa Fe jury found that 26 of 29 public statements by Meta and its executives about user data, misinformation, hate speech and equal enforcement were willfully deceptive. The jury sided with the state on 31 of 34 questions.", "fig": "43.9M", "cap": "violations found; the state counts 43,899,725, the verdict form 43,899,720", "status": "Judge Francis Mathew will set the penalty, up to $5,000 per violation.", "sources": [["Reuters via Engadget", "https://www.engadget.com/2269422/new-mexico-jury-rules-meta-misled-state-residents-about-data-privacy/"], ["Source New Mexico", "https://sourcenm.com/2026/09/25/new-mexico-jury-finds-facebook-at-fault-over-data-collection-misinformation-and-hate-speech/"], ["nm.news", "https://nm.news/2026/09/25/its-complicated-jury-finds-meta-misled-new-mexicans-43-9-million-times/"]], "response": "“We disagree with the verdict and will continue to defend ourselves against efforts to distort our record.”", "who": "Meta, 2026", "slug": "2026-a-second-jury-finds-43-9-million-deceptions", "url": "/record/2026-a-second-jury-finds-43-9-million-deceptions/"}];
const CREDITS=[{"id": "c-organ", "date": "2012-05", "title": "Organ donor status on profiles", "summary": "On the day Facebook let people share their donor status and linked them to state registries, new online registrations jumped 21-fold over the daily average, according to a Johns Hopkins study.", "fig": "21×", "ctx": "The surge faded within about two weeks, and registrations do not measure transplants.", "sources": [["Johns Hopkins", "https://hub.jhu.edu/2013/06/19/facebook-organ-donors"]]}, {"id": "c-safety", "date": "2014-10", "title": "Safety Check", "summary": "Safety Check lets people tell family and friends they are safe during a disaster. After the 2015 Paris attacks, 4.1 million people marked themselves safe within a day, and 360 million people were notified.", "fig": "4.1M", "ctx": "Facebook chose when to switch it on, and was criticized for using it after Paris but not after the Beirut bombing a day earlier.", "sources": [["Facebook announcement", "https://about.fb.com/news/2014/10/introducing-safety-check/"], ["VentureBeat", "https://venturebeat.com/technology/facebook-activates-its-safety-alert-feature-for-parisians"]]}, {"id": "c-whatsapp", "date": "2016-04", "title": "Default encryption for a billion people", "summary": "WhatsApp turned on end-to-end encryption for every message and call by default, using the open Signal Protocol.", "fig": "1B+", "ctx": "Meta still collects metadata such as who talks to whom, and encryption makes child-abuse material harder to detect.", "sources": [["eWeek", "https://www.eweek.com/mobile/whatsapp-user-chats-now-use-default-end-to-end-encryption/"]]}, {"id": "c-reports", "date": "2018-11", "title": "Human rights reports, published with findings against itself", "summary": "Meta commissioned and published outside assessments of its role in Myanmar, Sri Lanka, Indonesia, Cambodia and Israel-Palestine.", "ctx": "Each came after the harm, and Meta paid for them.", "sources": [["Myanmar assessment", "https://about.fb.com/2018/11/myanmar-hria/"]]}, {"id": "c-faces", "date": "2021-11", "title": "Face recognition switched off", "summary": "Facebook shut down its face-recognition system and said it would delete more than a billion face templates.", "ctx": "It came amid biometric lawsuits that have since cost Meta more than $2 billion.", "sources": [["ABC13 / AP", "https://abc13.com/post/meta-agreed-14b-settlement-texas-privacy-lawsuit-biometric-data-permission/15128086/"]]}, {"id": "c-pytorch", "date": "2022-09", "title": "PyTorch handed to a neutral foundation", "summary": "Meta built PyTorch, one of the most widely used tools for building AI, and gave it to the Linux Foundation. More than 18,000 organizations had adopted it.", "fig": "18,000", "ctx": "Meta’s Llama models are often called open source. Their license restrictions fall short of the Open Source Definition.", "sources": [["Linux Foundation", "https://www.linuxfoundation.org/press/press-release/meta-transitions-pytorch-to-the-linux-foundation"]]}, {"id": "c-fund", "date": "2022-11", "title": "Fundraising for nonprofits", "summary": "Meta says more than $7 billion had been raised for nonprofits through Facebook and Instagram, with birthday fundraisers a large share.", "fig": "$7B+", "ctx": "This is Meta’s own figure, and it has since scaled back some fundraising features.", "sources": [["Meta", "https://about.fb.com/news/2022/11/fundraise-for-nonprofits-giving-season/"]]}, {"id": "c-messenger", "date": "2023-12", "title": "Messenger encrypted by default", "summary": "Messenger began encrypting personal chats and calls by default for its more than one billion users. An EFF researcher called the move wholly a net positive.", "ctx": "The default arrived in December 2023, after the Nebraska case in 2022.", "sources": [["IEEE Spectrum", "https://spectrum.ieee.org/end-to-end-encryption-messenger"]]}];
const NOTES=[["“Instagram harms one in three teen girls.”", "The internal slide was about girls who already had body-image issues. Among them, 32% said Instagram made those feelings worse."], ["“87 million people were harvested.”", "That is Facebook’s upper estimate, and most were friends of the roughly 300,000 people who took the quiz."], ["“126 million Americans saw Russian propaganda.”", "Facebook said that many may have been served the posts. It could not say how many actually saw them."], ["“Meta paid $16 billion in scam ad revenue.”", "It was an internal projection for 2024 that also counted ads for banned goods. Meta disputes it."], ["“Facebook caused the Rohingya genocide.”", "Myanmar’s military carried out the atrocities. UN investigators and Amnesty found Facebook played a determining or substantial role in spreading hate. US courts dismissed the lawsuit on legal grounds without ruling on those facts."], ["“Meta handed abortion evidence to police.”", "Meta complied with a valid warrant that did not mention abortion. The messages were readable because they were not end-to-end encrypted."], ["“The FTC proved Meta is a monopoly.”", "The FTC lost. The judge ruled it had not shown Meta holds monopoly power today."], ["Settlement totals vary.", "Reports of the 2026 state settlement range from $12.1 billion to about $18 billion depending on what is counted. This site uses the guaranteed minimum."], ["Small conflicts between sources.", "Day-one organ donor sign-ups appear as 13,012 and 13,054 in the same study. Nepal Safety Check figures appear as 7 and 8.5 million. The Flo verdict is dated August 1, 2025; later dates are reporting dates. The September 2026 New Mexico verdict is counted as 43,899,720 violations on the verdict form and 43,899,725 by the state."]];
